def _has_business_facts(conn: sqlite3.Connection, tenant: str, ledger_id: str) -> bool:
    """该单据是否已留下任何收款/冲正/核销业务事实。

    冲正与核销留痕当前只在生效时写入，故任一留痕表存在该单据的行即代表已发生业务事实。
    留痕表以订单标识记账，而更正可能改名，因此经由 orders.ledger_id 不可变链路键关联：
    取该链路键下出现过的全部标识统一判定。
    """
    order_ids = [
        r["order_id"]
        for r in conn.execute(
            "SELECT order_id FROM orders WHERE tenant=? AND ledger_id=?", (tenant, ledger_id)
        ).fetchall()
    ]
    # ledger_id 在受理时写入且每行唯一，正常情况下恰为当前订单一行
    order_ids += [
        r["order_id"]
        for r in conn.execute(
            "SELECT DISTINCT order_id FROM correction_records WHERE tenant=? AND ledger_id=?",
            (tenant, ledger_id),
        ).fetchall()
    ]
    if not order_ids:
        return False
    placeholders = ",".join("?" for _ in order_ids)
    params = [tenant, *order_ids]
    for table in ("payment_records", "reversal_records", "reconciliation_records"):
        hit = conn.execute(
            f"SELECT 1 FROM {table} WHERE tenant=? AND order_id IN ({placeholders}) LIMIT 1",
            params,
        ).fetchone()
        if hit is not None:
            return True
    return False

